css:
.cosmic-toggle {
  position: relative;
  width: 140px;
  height: 70px;
  transform-style: preserve-3d;
  perspective: 500px;
}

.toggle {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(45deg, #ffcc00, #ff9900); /* Yellow gradient */
  border-radius: 35px;
  transition: 0.5s;
  transform-style: preserve-3d;
  box-shadow:
    0 0 20px rgba(0, 0, 0, 0.5),
    inset 0 0 15px rgba(255, 255, 255, 0.1);
  overflow: hidden;
}

.cosmos {
  position: absolute;
  inset: 0;
  background: radial-gradient(1px 1px at 10% 10%, #ffffff 100%, transparent),
    radial-gradient(1px 1px at 20% 20%, #ffffff 100%, transparent),
    radial-gradient(2px 2px at 30% 30%, #ffffff 100%, transparent),
    radial-gradient(1px 1px at 40% 40%, #ffffff 100%, transparent),
    radial-gradient(2px 2px at 50% 50%, #ffffff 100%, transparent),
    radial-gradient(1px 1px at 60% 60%, #ffffff 100%, transparent),
    radial-gradient(2px 2px at 70% 70%, #ffffff 100%, transparent),
    radial-gradient(1px 1px at 80% 80%, #ffffff 100%, transparent),
    radial-gradient(1px 1px at 90% 90%, #ffffff 100%, transparent);
  background-size: 200% 200%;
  opacity: 0.1;
  transition: 0.5s;
}

.toggle-orb {
  position: absolute;
  height: 62px;
  width: 62px;
  left: 4px;
  bottom: 4px;
  background: linear-gradient(145deg, #ffcc00, #ff9900); /* Yellow gradient */
  border-radius: 50%;
  transition: 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transform-style: preserve-3d;
  z-index: 2;
}

.inner-orb {
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: linear-gradient(
    145deg,
    #ffffff,
    #e6e6e6
  ); /* White to light gray */
  transition: 0.5s;
  overflow: hidden;
}

.inner-orb::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-conic-gradient(
    from 0deg,
    transparent 0deg,
    rgba(0, 0, 0, 0.1) 10deg,
    transparent 20deg
  );
  animation: patternRotate 10s linear infinite;
}

.ring {
  position: absolute;
  inset: -3px;
  border: 2px solid rgba(255, 255, 255, 0.3); /* Lighter border for contrast */
  border-radius: 50%;
  transition: 0.5s;
}

.toggle:checked + .slider {
  background: linear-gradient(
    45deg,
    #ff9900,
    #ffcc00
  ); /* Reverse gradient for checked state */
}

.toggle:checked + .slider .toggle-orb {
  transform: translateX(70px) rotate(360deg);
  background: linear-gradient(
    145deg,
    #ff9900,
    #ffcc00
  ); /* Lighter yellow gradient */
}

.toggle:checked + .slider .inner-orb {
  background: linear-gradient(
    145deg,
    #e6e6e6,
    #ffffff
  ); /* Light gray to white */
  transform: scale(0.9);
}

.toggle:checked + .slider .ring {
  border-color: rgba(255, 255, 255, 0.5); /* Brighter border on checked */
  animation: ringPulse 2s infinite;
}

.particles {
  position: absolute;
  width: 100%;
  height: 100%;
}

.particle {
  position: absolute;
  width: 4px;
  height: 4px;
  background: #ffcc00; /* Yellow particles */
  border-radius: 50%;
  opacity: 0;
}

.toggle:checked + .slider .particle {
  animation: particleBurst 1s ease-out infinite;
}

.particle:nth-child(1) {
  left: 20%;
  animation-delay: 0s;
}
.particle:nth-child(2) {
  left: 40%;
  animation-delay: 0.2s;
}
.particle:nth-child(3) {
  left: 60%;
  animation-delay: 0.4s;
}
.particle:nth-child(4) {
  left: 80%;
  animation-delay: 0.6s;
}
.particle:nth-child(5) {
  left: 30%;
  animation-delay: 0.8s;
}
.particle:nth-child(6) {
  left: 70%;
  animation-delay: 1s;
}

/* Animations */
@keyframes ringPulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.3;
  }
  50% {
    transform: scale(1.1);
    opacity: 0.6;
  }
}

@keyframes patternRotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

@keyframes particleBurst {
  0% {
    transform: translate(0, 0) scale(1);
    opacity: 1;
  }
  100% {
    transform: translate(
        calc(cos(var(--angle)) * 50px),
        calc(sin(var(--angle)) * 50px)
      )
      scale(0);
    opacity: 0;
  }
}

/* Hover effects */
.slider:hover .toggle-orb {
  filter: brightness(1.2);
  box-shadow:
    0 0 20px rgba(255, 255, 255, 0.5),
    0 0 40px rgba(255, 255, 255, 0.3);
}

.slider:hover .cosmos {
  opacity: 0.2;
  animation: cosmosPan 20s linear infinite;
}

@keyframes cosmosPan {
  0% {
    background-position: 0% 0%;
  }
  100% {
    background-position: 200% 200%;
  }
}

/* Active state */
.toggle:active + .slider .toggle-orb {
  transform: scale(0.95);
}

/* 3D effect on hover */
.cosmic-toggle:hover .slider {
  transform: rotateX(10deg) rotateY(10deg);
}

.cosmic-toggle:hover .toggle-orb {
  transform: translateZ(10px);
}

/* Shadow */
.toggle:checked + .slider::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at var(--x) var(--y),
    rgba(255, 255, 255, 0.2),
    transparent 50%
  );
  opacity: 0;
  animation: glowFollow 2s linear infinite;
}

@keyframes glowFollow {
  0%,
  100% {
    opacity: 0.2;
  }
  50% {
    opacity: 0.5;
  }
}
